UPDATE ai_memory_proposal SET status=#{status},revision=revision+1,decision_request_id=#{request},decision_actor_id=#{actor},decision_action=#{action},
  decision_expected_revision=#{row.revision},decision_expected_item_revision=#{expectedItem},accepted_version_id=#{version,jdbcType=VARBINARY}
WHERE tenant_id=#{row.tenantId} AND id=#{row.id} AND status='PENDING' AND revision=#{row.revision} AND decision_request_id IS NULL
